#pragma once
#include <Arduino.h>
#include <Preferences.h>
#include "StationConfig.h"
#include "GatewayStationDefaults.h" // generated by apply_lab_patch.py for this build

namespace gateway_stations {
#ifdef GATEWAY_STATIONS_DEFINE_STORAGE
Configuration active;
bool storage_error = false;
#else
extern Configuration active;
extern bool storage_error;
#endif
enum class LoadStatus { Missing, Loaded, Invalid };
static LoadStatus load(Configuration& config) {
  Preferences p;
  // A read-only open also fails when this namespace has never existed.
  if (!p.begin("gateway-nodes", true)) return LoadStatus::Missing;
  if (!p.isKey("config")) { p.end(); return LoadStatus::Missing; }
  uint8_t bytes[kBlobSize];
  bool ok=p.getBytesLength("config")==sizeof bytes &&
          p.getBytes("config",bytes,sizeof bytes)==sizeof bytes;
  p.end();
  return ok && decode(bytes,sizeof bytes,config) ? LoadStatus::Loaded : LoadStatus::Invalid;
}
static void begin() {
  const auto status=load(active);
  if(status==LoadStatus::Missing) {
    active=Configuration(); active.stations[0]=buildDefaultStation();
    active.stations[1].profile=cloud_gateway::rak4631RealWindProfile();
    Serial.println("[STATIONS] No saved stations; using existing build target in slot 1");
  } else if(status==LoadStatus::Invalid) {
    active=Configuration(); storage_error=true;
    Serial.println("[STATIONS] Invalid saved configuration; polling disabled until repaired in setup");
  }
  for(size_t i=0;i<kStationCount;++i) {
    const auto& s=active.stations[i];
    Serial.printf("[STATIONS] slot=%u node=%s enabled=%s\n",unsigned(i+1),s.node_id,s.enabled?"yes":"no");
  }
}
static bool save(const Configuration& config) {
  uint8_t bytes[kBlobSize];
  if(!encode(config,bytes,sizeof bytes)) return false;
  Preferences p; if(!p.begin("gateway-nodes",false)) return false;
  const bool ok=p.putBytes("config",bytes,sizeof bytes)==sizeof bytes;
  p.end(); return ok;
}
} // namespace gateway_stations
